const $=s=>document.querySelector(s),registerView=$('#register-view'),loginView=$('#login-view'),statusView=$('#status-view'),resetRequestView=$('#reset-request-view'),resetConfirmView=$('#reset-confirm-view');
const banks=[['001','Banco do Brasil'],['003','Banco da Amazônia'],['004','Banco do Nordeste'],['021','Banestes'],['033','Santander Brasil'],['041','Banrisul'],['047','Banco do Estado de Sergipe'],['070','BRB'],['077','Banco Inter'],['104','Caixa Econômica Federal'],['121','Agibank'],['197','Stone Instituição de Pagamento'],['208','BTG Pactual'],['212','Banco Original'],['237','Bradesco'],['260','Nu Pagamentos (Nubank)'],['290','PagBank'],['318','Banco BMG'],['323','Mercado Pago'],['336','C6 Bank'],['341','Itaú Unibanco'],['380','PicPay'],['389','Banco Mercantil do Brasil'],['422','Banco Safra'],['655','Banco Votorantim'],['748','Sicredi'],['756','Sicoob']];
$('#banks').innerHTML=banks.map(([code,name])=>`<option value="${code} - ${name}"></option>`).join('');
const api=async(url,options={})=>{const response=await fetch(url,{cache:'no-store',...options}),data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'Não foi possível concluir a operação.');return data};
const show=view=>{registerView.hidden=view!=='register';loginView.hidden=view!=='login';statusView.hidden=view!=='status';resetRequestView.hidden=view!=='reset-request';resetConfirmView.hidden=view!=='reset-confirm';scrollTo({top:0,behavior:'smooth'})};
$('#show-register').onclick=()=>show('register');$('#show-login').onclick=()=>show('login');
const onlyDigits=value=>String(value||'').replace(/\D/g,'');
const mask=(input,type)=>{let v=onlyDigits(input.value);if(type==='cpf')v=v.slice(0,11).replace(/(\d{3})(\d)/,'$1.$2').replace(/(\d{3})(\d)/,'$1.$2').replace(/(\d{3})(\d{1,2})$/,'$1-$2');if(type==='cnpj')v=v.slice(0,14).replace(/(\d{2})(\d)/,'$1.$2').replace(/(\d{3})(\d)/,'$1.$2').replace(/(\d{3})(\d)/,'$1/$2').replace(/(\d{4})(\d{1,2})$/,'$1-$2');if(type==='cep')v=v.slice(0,8).replace(/(\d{5})(\d)/,'$1-$2');input.value=v};
const form=$('#register-form');form.elements.cpf.addEventListener('input',e=>mask(e.target,'cpf'));form.elements.cnpj.addEventListener('input',e=>mask(e.target,'cnpj'));form.elements.cep.addEventListener('input',e=>mask(e.target,'cep'));
form.elements.possuiCnpj.addEventListener('change',e=>{$('#cnpj-field').hidden=!e.target.checked;form.elements.cnpj.required=e.target.checked;if(!e.target.checked)form.elements.cnpj.value=''});
form.elements.cep.addEventListener('blur',async()=>{const cep=onlyDigits(form.elements.cep.value),message=$('#cep-message');if(cep.length!==8)return;message.textContent='Consultando CEP…';try{const response=await fetch(`https://viacep.com.br/ws/${cep}/json/`),data=await response.json();if(data.erro)throw new Error();const parts=String(data.logradouro||'').split(' '),known=['Rua','Avenida','Travessa','Estrada','Rodovia','Alameda','Praça','Largo','Viela'];form.elements.tipoLogradouro.value=known.includes(parts[0])?parts.shift():form.elements.tipoLogradouro.value;form.elements.logradouro.value=parts.length?parts.join(' '):data.logradouro||'';form.elements.bairro.value=data.bairro||'';form.elements.cidade.value=data.localidade||'';form.elements.uf.value=data.uf||'';message.textContent='Endereço localizado.'}catch{message.textContent='CEP não localizado. Preencha o endereço manualmente.'}});
$('#bank-search').addEventListener('change',e=>{const match=banks.find(([code,name])=>`${code} - ${name}`===e.target.value);form.elements.bancoCodigo.value=match?.[0]||'';form.elements.bancoNome.value=match?.[1]||''});
form.addEventListener('submit',async e=>{e.preventDefault();const message=$('#register-message'),button=e.currentTarget.querySelector('button[type=submit]');message.className='form-message';message.textContent='';if(!form.reportValidity())return;const values=Object.fromEntries(new FormData(form));values.possuiCnpj=form.elements.possuiCnpj.checked;values.aceiteLgpd=form.elements.aceiteLgpd.checked;values.aceiteAutonomo=form.elements.aceiteAutonomo.checked;values.aceiteAntecedentes=form.elements.aceiteAntecedentes.checked;values.bancoCodigo=form.elements.bancoCodigo.value;values.bancoNome=form.elements.bancoNome.value;if(!values.bancoCodigo){message.textContent='Selecione um banco válido na lista.';return}button.disabled=true;try{await api('/api/montadores/cadastro',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(values)});form.reset();message.className='form-message success';message.textContent='Cadastro recebido. Abrindo seu acompanhamento…';await loadStatus();show('status')}catch(error){message.textContent=error.message}finally{button.disabled=false}});
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const loginForm=e.currentTarget,message=$('#login-message'),button=loginForm.querySelector('button[type=submit]'),values=Object.fromEntries(new FormData(loginForm));values.manterConectado=loginForm.elements.manterConectado.checked;button.disabled=true;message.textContent='';try{await api('/api/montadores/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(values)});loginForm.reset();await loadStatus();show('status')}catch(error){message.textContent=error.message}finally{button.disabled=false}});
$('#forgot-password').addEventListener('click',()=>{resetRequestView.querySelector('[name=email]').value=$('#login-form').elements.email.value;show('reset-request')});
document.querySelectorAll('.back-to-login').forEach(button=>button.addEventListener('click',()=>show('login')));
$('#reset-request-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button[type=submit]'),message=form.querySelector('.form-message');button.disabled=true;message.className='form-message';message.textContent='Enviando…';try{const data=await api('/api/montadores/senha-solicitar',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:form.elements.email.value})});message.className='form-message success';message.textContent=data.mensagem}catch(error){message.textContent=error.message}finally{button.disabled=false}});
$('#reset-confirm-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button[type=submit]'),message=form.querySelector('.form-message');message.className='form-message';if(form.elements.senha.value!==form.elements.confirmacao.value){message.textContent='As senhas não coincidem.';return}button.disabled=true;message.textContent='Salvando…';try{const data=await api('/api/montadores/senha-redefinir',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:form.elements.token.value,senha:form.elements.senha.value})});message.className='form-message success';message.textContent=data.mensagem;form.reset();setTimeout(()=>show('login'),1200)}catch(error){message.textContent=error.message}finally{button.disabled=false}});
const labels={CADASTRO_RECEBIDO:'Cadastro recebido',PENDENTE_DOCUMENTO:'Pendente de certidão',EM_ANALISE:'Em análise',APROVADO:'Aprovado',REJEITADO:'Não aprovado',SUSPENSO:'Suspenso',PENDENTE:'Pendente',REJEITADO:'Rejeitado'};
const formatDate=value=>value?new Date(value).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'}):'—';
const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
async function loadStatus(){const data=await api('/api/montadores/status');$('#status-name').textContent=data.montador.nomeCompleto;const approved=data.montador.statusCadastro==='APROVADO';$('#status-card').innerHTML=`<div class="status-card"><article><span>Status do cadastro</span><strong class="${approved?'approved':'pending'}">${labels[data.montador.statusCadastro]||data.montador.statusCadastro}</strong></article><article><span>Certidão</span><strong>${labels[data.montador.certidaoStatus]||data.montador.certidaoStatus}</strong></article><article><span>Última atualização</span><strong>${formatDate(data.montador.atualizadoEm)}</strong></article></div>${data.pendencias.certidao?'<div class="notice"><strong>Pendência obrigatória:</strong> anexe uma certidão válida para que o cadastro possa ser analisado e aprovado.<a class="notice-action" href="#certificate-form">Anexar certidão agora</a></div>':''}`;$('#documents-list').innerHTML=data.documentos.length?data.documentos.map(doc=>`<div class="document"><div><strong>${doc.tipo==='CERTIDAO_ANTECEDENTES'?'Certidão de antecedentes':'NFS-e'}</strong><small>${escapeHtml(doc.nome_arquivo)} · ${formatDate(doc.criado_em)}</small></div><span>${labels[doc.status_revisao]||doc.status_revisao}</span></div>`).join(''):'<p>Nenhum documento enviado.</p>'}
const fileBase64=file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)});
async function upload(formElement,tipo){const message=formElement.querySelector('.form-message'),button=formElement.querySelector('button'),file=formElement.elements.file.files[0];if(!file)return;button.disabled=true;message.textContent='Enviando…';try{const body={tipo,fileName:file.name,mimeType:file.type,data:await fileBase64(file)};if(tipo==='NOTA_FISCAL_SERVICO'){body.valorTotal=formElement.elements.valorTotal.value;body.referenciaPagamento=formElement.elements.referenciaPagamento.value}await api('/api/montadores/documento',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});formElement.reset();message.className='form-message success';message.textContent='Documento enviado para revisão.';await loadStatus()}catch(error){message.className='form-message';message.textContent=error.message}finally{button.disabled=false}}
$('#certificate-form').addEventListener('submit',e=>{e.preventDefault();upload(e.currentTarget,'CERTIDAO_ANTECEDENTES')});$('#invoice-form').addEventListener('submit',e=>{e.preventDefault();upload(e.currentTarget,'NOTA_FISCAL_SERVICO')});
$('#logout').addEventListener('click',async()=>{await fetch('/api/montadores/logout',{method:'POST'});show('login')});
const resetToken=new URLSearchParams(location.search).get('redefinir');if(resetToken){$('#reset-confirm-form').elements.token.value=resetToken;show('reset-confirm')}else api('/api/montadores/status').then(()=>loadStatus()).then(()=>show('status')).catch(()=>{});

const moneyBR=value=>Number(value||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const dateInput=value=>{const date=value?new Date(value):new Date();return new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(date)};
const operationId=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(16).slice(2)}`;
let operationReady=false;

function setupOperations(){
  if(operationReady)return;
  operationReady=true;
  const start=new Date();start.setDate(1);
  const section=document.createElement('section');
  section.id='assembler-operations';
  section.className='operation-area';
  section.innerHTML=`<div class="operation-heading"><span>OPERAÇÃO DO MONTADOR</span><h2>Serviços e repasses</h2><p>No navegador você pode aceitar propostas e consultar os atendimentos. Fotos e finalização são exclusivas do aplicativo móvel.</p></div><nav class="operation-tabs" aria-label="Áreas operacionais"><button data-operation-view="PENDENTES_ACEITE" class="active">Para aceitar</button><button data-operation-view="PENDENTES_EXECUCAO">Para executar</button><button data-operation-view="PENDENTES_REPASSE">Repasse pendente</button><button data-operation-view="PAGAMENTOS">Pagamentos gerados</button><button data-operation-view="RECEBIDOS">Repasses recebidos</button></nav><div id="operation-history-filter" class="operation-filter" hidden><label>De<input id="operation-from" type="date" value="${dateInput(start)}"></label><label>Até<input id="operation-to" type="date" value="${dateInput(new Date())}"></label><button id="operation-filter-button" type="button" class="secondary">Filtrar</button></div><p id="operation-message" class="form-message" role="status"></p><div id="operation-list" class="operation-list"></div>`;
  statusView.appendChild(section);
  section.querySelector('.operation-tabs').addEventListener('click',event=>{const button=event.target.closest('[data-operation-view]');if(!button)return;section.querySelectorAll('[data-operation-view]').forEach(item=>item.classList.toggle('active',item===button));loadOperation(button.dataset.operationView)});
  section.querySelector('#operation-filter-button').onclick=()=>loadOperation('RECEBIDOS');
  section.querySelector('#operation-list').addEventListener('click',operationClick);
  section.querySelector('#operation-list').addEventListener('submit',invoiceSubmit);
}

const serviceStatusLabel={PENDENTE_ACEITE:'Aguardando seu aceite',ACEITO:'Aceito',EM_EXECUCAO:'Em execução',CONCLUIDO:'Concluído'};
function serviceCard(service,view){
  const privateDetails=service.nomeCliente?`<dl><div><dt>Cliente</dt><dd>${escapeHtml(service.nomeCliente)}</dd></div><div><dt>Contato</dt><dd>${escapeHtml(service.telefoneCliente||'—')}</dd></div><div class="wide"><dt>Endereço</dt><dd>${escapeHtml(service.endereco||'—')} · ${escapeHtml(service.bairro||'')} · ${escapeHtml(service.cidade||'')}</dd></div>${service.referencia?`<div class="wide"><dt>Referência</dt><dd>${escapeHtml(service.referencia)}</dd></div>`:''}</dl>`:`<p class="privacy-note">Os dados pessoais e o endereço completo serão liberados depois do aceite.</p>`;
  const actions=view==='PENDENTES_ACEITE'?`<div class="service-actions"><button type="button" data-service-action="ACEITAR" data-id="${service.id}">Aceitar serviço</button><button type="button" class="secondary" data-service-action="RECUSAR" data-id="${service.id}">Recusar</button></div>`:'';
  return `<article class="service-card"><header><div><small>ATENDIMENTO #${escapeHtml(service.numeroAtendimento)}</small><h3>${escapeHtml(service.descricaoServico)}</h3></div><span>${serviceStatusLabel[service.status]||escapeHtml(service.status)}</span></header><dl><div><dt>Agendamento</dt><dd>${formatDate(service.agendadoPara)}</dd></div><div><dt>Localidade</dt><dd>${escapeHtml(service.bairro)} · ${escapeHtml(service.cidade)}</dd></div><div><dt>Repasse</dt><dd>${moneyBR(service.valorRepasse)}</dd></div>${service.fotos?`<div><dt>Fotos</dt><dd>${service.fotos}</dd></div>`:''}</dl>${privateDetails}${actions}${view==='PENDENTES_EXECUCAO'?'<p class="app-only-note">Use o aplicativo móvel para registrar deslocamento, chegada, fotos e finalização.</p>':''}</article>`;
}

function paymentCard(payment,received=false){
  const items=payment.itens.map(item=>`<li><span>#${escapeHtml(item.numeroAtendimento)} · ${escapeHtml(item.descricaoServico)}</span><strong>${moneyBR(item.valor)}</strong></li>`).join('');
  const invoice=['AGUARDANDO_NFSE','NFSE_REJEITADA'].includes(payment.status)?`<form class="payment-invoice-form" data-payment-id="${payment.id}"><p>A NFS-e deve ter o valor total exato deste pagamento.</p><input name="valorTotal" type="hidden" value="${payment.valorTotal}"><input name="file" type="file" accept="application/pdf,image/jpeg,image/png" required><button type="submit">Anexar NFS-e de ${moneyBR(payment.valorTotal)}</button><p class="form-message"></p></form>`:'';
  return `<article class="payment-card"><header><div><small>PAGAMENTO #${escapeHtml(payment.numero)} · ${escapeHtml(payment.documentoBancario)}</small><h3>${moneyBR(payment.valorTotal)}</h3></div><span class="payment-status">${escapeHtml(payment.status)}</span></header><ul>${items}</ul>${payment.nfseNome?`<p>NFS-e: <strong>${escapeHtml(payment.nfseNome)}</strong> · ${escapeHtml(payment.nfseStatus||'')}</p>`:''}${invoice}${received?`<p>Pago em ${formatDate(payment.pagoEm)}</p>`:''}</article>`;
}

async function loadOperation(view='PENDENTES_ACEITE'){
  setupOperations();
  const list=$('#operation-list'),message=$('#operation-message'),filter=$('#operation-history-filter');
  filter.hidden=view!=='RECEBIDOS';message.textContent='';list.innerHTML='<p>Carregando…</p>';
  try{
    if(['PENDENTES_ACEITE','PENDENTES_EXECUCAO','PENDENTES_REPASSE'].includes(view)){
      const data=await api(`/api/montadores/servicos?view=${view}`);list.innerHTML=data.servicos.length?data.servicos.map(item=>serviceCard(item,view)).join(''):'<p class="operation-empty">Nenhum serviço nesta situação.</p>';
    }else{
      const query=view==='RECEBIDOS'?`?view=RECEBIDOS&historico=1&de=${encodeURIComponent($('#operation-from').value)}&ate=${encodeURIComponent($('#operation-to').value)}`:'';
      const data=await api('/api/montadores/pagamentos'+query);list.innerHTML=data.pagamentos.length?data.pagamentos.map(item=>paymentCard(item,view==='RECEBIDOS')).join(''):'<p class="operation-empty">Nenhum pagamento nesta situação.</p>';
    }
  }catch(error){list.innerHTML='';message.textContent=error.message}
}

async function operationClick(event){
  const button=event.target.closest('[data-service-action]');if(!button)return;
  const original=button.textContent,action=button.dataset.serviceAction;button.disabled=true;button.textContent=action==='ACEITAR'?'Aceitando…':'Recusando…';
  try{const data=await api('/api/montadores/servicos',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:button.dataset.id,acao:action,operacaoId:operationId()})});$('#operation-message').className='form-message success';$('#operation-message').textContent=data.mensagem;await loadOperation('PENDENTES_ACEITE')}catch(error){$('#operation-message').className='form-message';$('#operation-message').textContent=error.message;button.disabled=false;button.textContent=original}
}

async function invoiceSubmit(event){
  const formElement=event.target.closest('.payment-invoice-form');if(!formElement)return;event.preventDefault();
  const file=formElement.elements.file.files[0],button=formElement.querySelector('button'),message=formElement.querySelector('.form-message');if(!file)return;button.disabled=true;message.textContent='Enviando…';
  try{await api('/api/montadores/pagamento-documento',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({pagamentoId:formElement.dataset.paymentId,valorTotal:formElement.elements.valorTotal.value,fileName:file.name,mimeType:file.type,data:await fileBase64(file)})});message.className='form-message success';message.textContent='NFS-e enviada para análise.';await loadOperation('PAGAMENTOS')}catch(error){message.className='form-message';message.textContent=error.message;button.disabled=false}
}

const loadBaseStatus=loadStatus;
loadStatus=async function(){await loadBaseStatus();const data=await api('/api/montadores/status');if(data.montador.statusCadastro==='APROVADO'){setupOperations();await loadOperation('PENDENTES_ACEITE')}};
